arguments.rule_content:
rule sigma "Cobalt Strike Beacon C2 Activity" {
  meta:
    description: "Cobalt Strike Beacon C2 Activity"
    author: "John Doe"
  condition:
    process where process.name == "powershell.exe" and process.command_line == "/C powershell.exe -nop -c Add-Type -MemberDefinition "[DllImport(""kernel32.dll"")]
  public static extern IntPtr VirtualAlloc(IntPtr lpAddress, uint dwSize, uint flAllocationType, uint flProtect);"
  public static void AllocMemory() {
    IntPtr ptr = VirtualAlloc(0, 1024, 0x3000, 0x40);
    if (ptr != IntPtr.Zero) {
      Console.WriteLine("Allocated memory at address {0}", ptr);
    }
  }
"
  AllocMemory();
"
  "
}
